<?php
defined( 'ABSPATH' ) || exit;

function awd_lm_analytics_duration( $seconds ) {
	$seconds = max( 0, absint( $seconds ) );
	if ( $seconds < 60 ) { return $seconds . 's'; }
	$minutes = (int) floor( $seconds / 60 );
	$remainder = $seconds % 60;
	return $minutes . 'm ' . $remainder . 's';
}

function awd_lm_analytics_source_label( $session ) {
	if ( ! empty( $session->utm_source ) ) { return $session->utm_source; }
	$host = wp_parse_url( $session->referrer ?? '', PHP_URL_HOST );
	return $host ? $host : 'direct';
}

function awd_lm_analytics_page() {
	if ( ! current_user_can( 'manage_options' ) ) { wp_die( 'Forbidden', 403 ); }
	awd_lm_maybe_upgrade_analytics_tables();
	global $wpdb;
	$tables = awd_lm_analytics_tables();
	$email_tables = awd_lm_email_tables();
	$days = isset( $_GET['days'] ) ? absint( $_GET['days'] ) : 30;
	if ( ! in_array( $days, array( 7, 30, 90, 365 ), true ) ) { $days = 30; }
	$definitions = function_exists( 'awd_lm_definitions' ) ? awd_lm_definitions() : array( 'gloriafood' => array( 'name' => 'GloriaFood Alternative' ) );
	$requested_landing = sanitize_key( $_GET['landing_id'] ?? 'all' );
	$landing_id = isset( $definitions[ $requested_landing ] ) ? $requested_landing : '';
	$landing_label = $landing_id ? ( $definitions[ $landing_id ]['name'] ?? $landing_id ) : 'All landings';
	$session_filter = $landing_id ? $wpdb->prepare( ' AND landing_id=%s', $landing_id ) : '';
	$session_alias_filter = $landing_id ? $wpdb->prepare( ' AND s.landing_id=%s', $landing_id ) : '';
	$event_filter = $landing_id ? $wpdb->prepare( ' AND landing_id=%s', $landing_id ) : '';
	$since = gmdate( 'Y-m-d H:i:s', time() - $days * DAY_IN_SECONDS );
	$session_count = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$tables['sessions']} WHERE started_at >= %s$session_filter", $since ) );
	$lead_count = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$tables['sessions']} WHERE started_at >= %s AND lead_id > 0$session_filter", $since ) );
	$event_count = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$tables['events']} WHERE occurred_at >= %s$event_filter", $since ) );
	$avg_duration = (int) $wpdb->get_var( $wpdb->prepare( "SELECT AVG(TIMESTAMPDIFF(SECOND,started_at,last_seen_at)) FROM {$tables['sessions']} WHERE started_at >= %s$session_filter", $since ) );
	$avg_engaged = (int) $wpdb->get_var( $wpdb->prepare( "SELECT AVG(engaged_seconds) FROM {$tables['sessions']} WHERE started_at >= %s$session_filter", $since ) );
	$conversion = $session_count ? round( 100 * $lead_count / $session_count, 1 ) : 0;
	$sources = $wpdb->get_results( $wpdb->prepare( "SELECT IF(utm_source='',IF(referrer='','direct','referral'),utm_source) source,utm_medium medium,COUNT(*) sessions,SUM(lead_id>0) leads FROM {$tables['sessions']} WHERE started_at >= %s$session_filter GROUP BY source,utm_medium ORDER BY sessions DESC LIMIT 15", $since ) );
	$campaigns = $wpdb->get_results( $wpdb->prepare( "SELECT s.utm_campaign campaign,COALESCE(MAX(l.name),MAX(c.name)) campaign_name,s.utm_source source,COUNT(*) sessions,SUM(s.lead_id>0) leads FROM {$tables['sessions']} s LEFT JOIN {$email_tables['campaigns']} c ON s.utm_id=CONCAT('awd-email-campaign-',c.id) LEFT JOIN {$email_tables['lists']} l ON s.utm_id=l.utm_id WHERE s.started_at >= %s AND s.utm_campaign<>''$session_alias_filter GROUP BY s.utm_campaign,s.utm_source ORDER BY sessions DESC LIMIT 15", $since ) );
	$event_rows = $wpdb->get_results( $wpdb->prepare( "SELECT event_name,COUNT(*) total FROM {$tables['events']} WHERE occurred_at >= %s$event_filter GROUP BY event_name", $since ) );
	$event_map = array();
	foreach ( $event_rows as $event_row ) { $event_map[ $event_row->event_name ] = (int) $event_row->total; }
	$sections = $wpdb->get_results( $wpdb->prepare( "SELECT section_id,MAX(section_name) section_name,COUNT(*) views,COUNT(DISTINCT session_id) sessions FROM {$tables['events']} WHERE occurred_at >= %s AND event_name='section_view' AND section_id<>''$event_filter GROUP BY section_id ORDER BY sessions DESC LIMIT 25", $since ) );
	$identity_select = "es.recipient_email recognized_email,COALESCE(NULLIF(em.company,''),NULLIF(ee.standalone_company,''),'') recognized_company,TRIM(CONCAT(COALESCE(NULLIF(em.first_name,''),ee.standalone_first_name,''),' ',COALESCE(NULLIF(em.last_name,''),ee.standalone_last_name,''))) recognized_name,ee.name recognized_email_name";
	$identity_joins = " LEFT JOIN {$email_tables['sends']} es ON es.id=s.email_send_id LEFT JOIN {$email_tables['emails']} ee ON ee.id=es.email_id LEFT JOIN {$email_tables['members']} em ON em.list_id=ee.list_id AND LOWER(em.email)=LOWER(es.recipient_email)";
	$recent = $wpdb->get_results( $wpdb->prepare( "SELECT s.*,COALESCE(l.name,c.name) campaign_name,TIMESTAMPDIFF(SECOND,s.started_at,s.last_seen_at) duration_seconds,$identity_select FROM {$tables['sessions']} s LEFT JOIN {$email_tables['campaigns']} c ON s.utm_id=CONCAT('awd-email-campaign-',c.id) LEFT JOIN {$email_tables['lists']} l ON s.utm_id=l.utm_id $identity_joins WHERE s.started_at >= %s$session_alias_filter ORDER BY s.started_at DESC LIMIT 100", $since ) );
	$detail_id = isset( $_GET['session'] ) ? absint( $_GET['session'] ) : 0;
	$detail = $detail_id ? $wpdb->get_row( $wpdb->prepare( "SELECT s.*,COALESCE(l.name,c.name) campaign_name,TIMESTAMPDIFF(SECOND,s.started_at,s.last_seen_at) duration_seconds,$identity_select FROM {$tables['sessions']} s LEFT JOIN {$email_tables['campaigns']} c ON s.utm_id=CONCAT('awd-email-campaign-',c.id) LEFT JOIN {$email_tables['lists']} l ON s.utm_id=l.utm_id $identity_joins WHERE s.id=%d$session_alias_filter", $detail_id ) ) : null;
	$detail_events = $detail ? $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['events']} WHERE session_id=%d ORDER BY occurred_at,id LIMIT 500", $detail_id ) ) : array();
	$detail_sections = array();
	$detail_form_status = 'Not started';
	foreach ( $detail_events as $event ) {
		if ( 'section_view' === $event->event_name && $event->section_id ) {
			$detail_sections[] = array( 'id' => $event->section_id, 'name' => $event->section_name ?: $event->section_id, 'time' => $event->occurred_at );
		}
		if ( 'form_start' === $event->event_name ) { $detail_form_status = 'Started'; }
		if ( 'form_submit' === $event->event_name ) { $detail_form_status = 'Submitted'; }
		if ( 'form_validation_error' === $event->event_name ) { $detail_form_status = 'Error'; }
		if ( 'lead_created' === $event->event_name ) { $detail_form_status = 'Lead created'; }
	}
	$dashboard_url = admin_url( 'admin-post.php?action=awd_lm_analytics' );
	$landing_query_value = $landing_id ?: 'all';
	?><!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo $detail_id ? 'Session #' . esc_html( $detail_id ) . ' · Analytics' : 'Analytics'; ?></title>
<style>
body{margin:28px;font:14px/1.45 system-ui;background:#f5f8f6;color:#182019}main{max-width:1440px;margin:auto}a{color:#087a4c;font-weight:750;text-decoration:none}.bar,.filters,.cards{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.bar{justify-content:space-between}.filters a{padding:7px 10px;border-radius:7px;background:#e5eee8}.filters a.on{background:#087a4c;color:#fff}.button,.session-open{display:inline-flex;align-items:center;justify-content:center;padding:9px 13px;border:1px solid #bcd8c5;border-radius:8px;background:#fff;color:#087a4c}.button.primary,.session-open{background:#087a4c;color:#fff;border-color:#087a4c}.cards{margin:22px 0}.metric{min-width:150px;flex:1;background:#fff;border:1px solid #d6e8dc;border-radius:14px;padding:18px}.metric strong{display:block;font-size:28px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{background:#fff;border:1px solid #d6e8dc;border-radius:14px;padding:20px;overflow:auto}.panel h2{margin-top:0}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid #e1ebe4}th{color:#52635a}.funnel{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.funnel div,.summary-item{background:#edf6f0;padding:14px;border-radius:10px;text-align:center}.funnel strong,.summary-item strong{display:block;font-size:21px}.muted{color:#65756c}.badge{display:inline-block;background:#edf6f0;border-radius:999px;padding:4px 8px;font-weight:750}.timeline td:first-child{white-space:nowrap}.session-summary{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:16px 0}.utm{word-break:break-all;background:#f7faf8;border:1px solid #e1ebe4;padding:12px;border-radius:10px}.lead{font-weight:850;color:#087a4c}.view-path{margin:0 0 20px;padding:0;list-style:none;display:grid;gap:8px}.view-path li{display:grid;grid-template-columns:90px 1fr;gap:12px;padding:10px 12px;background:#f7faf8;border-left:3px solid #cda574;border-radius:6px}.view-path time{font-variant-numeric:tabular-nums;color:#65756c}@media(max-width:900px){.grid{grid-template-columns:1fr}.session-summary{grid-template-columns:1fr 1fr}.funnel{grid-template-columns:1fr 1fr}}
</style></head><body><main>
<?php if ( $detail_id ) : ?>
<div class="bar"><div><h1>Session #<?php echo esc_html( $detail_id ); ?></h1><p class="muted"><?php echo esc_html( $landing_label ); ?> · individual session report · chronological activity only</p></div><div class="bar"><a class="button" href="<?php echo esc_url( add_query_arg( array( 'days' => $days, 'landing_id' => $landing_query_value ), $dashboard_url ) . '#sessions' ); ?>">← All sessions</a><a class="button primary" href="<?php echo esc_url( add_query_arg( array( 'days' => $days, 'landing_id' => $landing_query_value, 'session' => $detail_id ), $dashboard_url ) ); ?>">Refresh</a></div></div>
