<section class="panel" style="margin-top:20px"><h2>Session not found</h2><p>This session no longer exists or the URL is invalid.</p></section>
<?php else : ?>
<section class="panel" style="margin-top:20px"><div class="bar"><div><h2>Session overview</h2><p class="muted">Entered <?php echo esc_html( get_date_from_gmt( $detail->started_at, 'Y-m-d H:i:s' ) ); ?> · last activity <?php echo esc_html( get_date_from_gmt( $detail->last_seen_at, 'Y-m-d H:i:s' ) ); ?></p></div></div>
<div class="session-summary"><div class="summary-item"><span>Landing</span><strong><?php echo esc_html( $definitions[ $detail->landing_id ]['name'] ?? $detail->landing_id ); ?></strong></div><div class="summary-item"><span>Source</span><strong><?php echo esc_html( awd_lm_analytics_source_label( $detail ) ); ?></strong></div><div class="summary-item"><span>Duration</span><strong><?php echo esc_html( awd_lm_analytics_duration( $detail->duration_seconds ) ); ?></strong></div><div class="summary-item"><span>Active time</span><strong><?php echo esc_html( awd_lm_analytics_duration( $detail->engaged_seconds ) ); ?></strong></div><div class="summary-item"><span>Language / device</span><strong><?php echo esc_html( strtoupper( $detail->language ) . ' · ' . ( $detail->device_type ?: 'unknown' ) ); ?></strong></div><div class="summary-item"><span>Form / lead</span><strong><?php echo esc_html( $detail_form_status ); ?><?php echo $detail->lead_id ? ' · #' . esc_html( $detail->lead_id ) : ''; ?></strong></div></div>
<?php if ( $detail->email_send_id ) : ?><p class="utm"><strong>Recognized email recipient</strong><br>Company: <?php echo esc_html( $detail->recognized_company ?: '—' ); ?><br>Contact: <?php echo esc_html( $detail->recognized_name ?: '—' ); ?><br>Email: <?php echo esc_html( $detail->recognized_email ?: '—' ); ?><br>Sent email: <?php echo esc_html( $detail->recognized_email_name ?: '—' ); ?> · Send #<?php echo esc_html( $detail->email_send_id ); ?></p><?php endif; ?>
<p class="utm"><strong>Entry URL:</strong> <?php echo esc_html( $detail->landing_url ?: '—' ); ?><br><strong>Referrer:</strong> <?php echo esc_html( $detail->referrer ?: '—' ); ?><br><strong>Campaign name:</strong> <?php echo esc_html( $detail->campaign_name ?: '—' ); ?><br><strong>UTM:</strong> source=<?php echo esc_html( $detail->utm_source ?: '—' ); ?> · medium=<?php echo esc_html( $detail->utm_medium ?: '—' ); ?> · campaign=<?php echo esc_html( $detail->utm_campaign ?: '—' ); ?> · content=<?php echo esc_html( $detail->utm_content ?: '—' ); ?> · term=<?php echo esc_html( $detail->utm_term ?: '—' ); ?> · id=<?php echo esc_html( $detail->utm_id ?: '—' ); ?></p>
<h3>Viewed blocks chronology</h3><?php if ( $detail_sections ) : ?><ol class="view-path"><?php foreach ( $detail_sections as $view ) : ?><li><time><?php echo esc_html( get_date_from_gmt( $view['time'], 'H:i:s' ) ); ?></time><span><strong><?php echo esc_html( $view['name'] ); ?></strong><br><span class="muted">ID: <?php echo esc_html( $view['id'] ); ?></span></span></li><?php endforeach; ?></ol><?php else : ?><p>No section views recorded.</p><?php endif; ?>
<h3>Event timeline</h3><table class="timeline"><thead><tr><th>Time</th><th>Event</th><th>Block ID / name</th><th>Element</th></tr></thead><tbody><?php foreach ( $detail_events as $event ) : ?><tr><td><?php echo esc_html( get_date_from_gmt( $event->occurred_at, 'Y-m-d H:i:s' ) ); ?></td><td><span class="badge"><?php echo esc_html( $event->event_name ); ?></span></td><td><?php echo esc_html( $event->section_id ?: '—' ); ?><br><span class="muted"><?php echo esc_html( $event->section_name ); ?></span></td><td><?php echo esc_html( $event->element_label ?: $event->element_id ?: '—' ); ?></td></tr><?php endforeach; ?><?php if ( ! $detail_events ) : ?><tr><td colspan="4">No events recorded for this session.</td></tr><?php endif; ?></tbody></table></section>
<?php endif; ?>
</main></body></html><?php exit; ?>
<?php endif; ?>
<div class="bar" id="overview"><div><h1>Analytics</h1><p class="muted"><?php echo esc_html( $landing_label ); ?> · anonymous sessions. No IP addresses or form values are stored.</p></div><div class="filters"><a class="<?php echo '' === $landing_id ? 'on' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'days' => $days, 'landing_id' => 'all' ), $dashboard_url ) ); ?>">All landings</a><?php foreach ( $definitions as $key => $definition ) : ?><a class="<?php echo $landing_id === $key ? 'on' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'days' => $days, 'landing_id' => $key ), $dashboard_url ) ); ?>"><?php echo esc_html( $definition['name'] ?? $key ); ?></a><?php endforeach; ?><?php foreach ( array( 7,30,90,365 ) as $range ) : ?><a class="<?php echo $days === $range ? 'on' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'days' => $range, 'landing_id' => $landing_query_value ), $dashboard_url ) ); ?>"><?php echo esc_html( $range ); ?> days</a><?php endforeach; ?></div></div>
<div class="cards"><div class="metric"><span>Sessions</span><strong><?php echo esc_html( $session_count ); ?></strong></div><div class="metric"><span>Events</span><strong><?php echo esc_html( $event_count ); ?></strong></div><div class="metric"><span>Leads</span><strong><?php echo esc_html( $lead_count ); ?></strong></div><div class="metric"><span>Conversion</span><strong><?php echo esc_html( $conversion ); ?>%</strong></div><div class="metric"><span>Avg. duration</span><strong><?php echo esc_html( awd_lm_analytics_duration( $avg_duration ) ); ?></strong></div><div class="metric"><span>Avg. active time</span><strong><?php echo esc_html( awd_lm_analytics_duration( $avg_engaged ) ); ?></strong></div></div>
<section class="panel"><h2>Funnel</h2><div class="funnel"><?php foreach ( array( 'page_view'=>'Page views','cta_click'=>'CTA clicks','form_start'=>'Form starts','lead_created'=>'Leads' ) as $key=>$label ) : ?><div><span><?php echo esc_html( $label ); ?></span><strong><?php echo esc_html( $event_map[ $key ] ?? 0 ); ?></strong></div><?php endforeach; ?></div></section>
<div class="grid" style="margin-top:20px"><section class="panel"><h2>Sources</h2><table><thead><tr><th>Source / medium</th><th>Sessions</th><th>Leads</th></tr></thead><tbody><?php foreach ( $sources as $row ) : ?><tr><td><strong><?php echo esc_html( $row->source ); ?></strong><br><span class="muted"><?php echo esc_html( $row->medium ?: '—' ); ?></span></td><td><?php echo esc_html( $row->sessions ); ?></td><td><?php echo esc_html( $row->leads ); ?></td></tr><?php endforeach; ?><?php if ( ! $sources ) : ?><tr><td colspan="3">No sessions yet.</td></tr><?php endif; ?></tbody></table></section><section class="panel"><h2>Campaigns</h2><table><thead><tr><th>Name / UTM</th><th>Source</th><th>Sessions</th><th>Leads</th></tr></thead><tbody><?php foreach ( $campaigns as $row ) : ?><tr><td><strong><?php echo esc_html( $row->campaign_name ?: $row->campaign ); ?></strong><br><span class="muted"><?php echo esc_html( $row->campaign ); ?></span></td><td><?php echo esc_html( $row->source ); ?></td><td><?php echo esc_html( $row->sessions ); ?></td><td><?php echo esc_html( $row->leads ); ?></td></tr><?php endforeach; ?><?php if ( ! $campaigns ) : ?><tr><td colspan="4">No tagged campaigns yet.</td></tr><?php endif; ?></tbody></table></section></div>
<section class="panel" style="margin-top:20px"><h2>Viewed blocks</h2><table><thead><tr><th>Block ID</th><th>Name</th><th>Sessions</th><th>Views</th></tr></thead><tbody><?php foreach ( $sections as $section ) : ?><tr><td><strong><?php echo esc_html( $section->section_id ); ?></strong></td><td><?php echo esc_html( $section->section_name ?: '—' ); ?></td><td><?php echo esc_html( $section->sessions ); ?></td><td><?php echo esc_html( $section->views ); ?></td></tr><?php endforeach; ?><?php if ( ! $sections ) : ?><tr><td colspan="4">No block views yet.</td></tr><?php endif; ?></tbody></table></section>
<section class="panel" id="sessions" style="margin-top:20px"><div class="bar"><div><h2>Sessions</h2><p class="muted">Open a session to see its individual chronology in a separate tab.</p></div></div><table><thead><tr><th>Entered</th><th>Landing</th><th>Recognized company</th><th>Source / campaign</th><th>Language / device</th><th>Duration</th><th>Active</th><th>Events</th><th>Lead</th><th>Details</th></tr></thead><tbody><?php foreach ( $recent as $session ) : ?><?php $session_url = add_query_arg( array( 'days' => $days, 'landing_id' => $landing_query_value, 'session' => $session->id ), $dashboard_url ); ?><tr><td><a href="<?php echo esc_url( $session_url ); ?>" target="_blank" rel="noopener"><?php echo esc_html( get_date_from_gmt( $session->started_at, 'Y-m-d H:i' ) ); ?></a></td><td><?php echo esc_html( $definitions[ $session->landing_id ]['name'] ?? $session->landing_id ); ?></td><td><?php echo esc_html( $session->recognized_company ?: '—' ); ?><?php if ( $session->recognized_email ) : ?><br><span class="muted"><?php echo esc_html( $session->recognized_email ); ?></span><?php endif; ?></td><td><?php echo esc_html( awd_lm_analytics_source_label( $session ) ); ?><br><span class="muted"><?php echo esc_html( $session->campaign_name ?: $session->utm_campaign ?: '—' ); ?></span></td><td><?php echo esc_html( strtoupper( $session->language ) . ' · ' . ( $session->device_type ?: 'unknown' ) ); ?></td><td><?php echo esc_html( awd_lm_analytics_duration( $session->duration_seconds ) ); ?></td><td><?php echo esc_html( awd_lm_analytics_duration( $session->engaged_seconds ) ); ?></td><td><?php echo esc_html( $session->event_count ); ?></td><td><?php echo $session->lead_id ? '<span class="lead">#' . esc_html( $session->lead_id ) . '</span>' : '—'; ?></td><td><a class="session-open" href="<?php echo esc_url( $session_url ); ?>" target="_blank" rel="noopener">Open ↗</a></td></tr><?php endforeach; ?><?php if ( ! $recent ) : ?><tr><td colspan="10">No sessions yet.</td></tr><?php endif; ?></tbody></table></section>
</main></body></html><?php exit;
